import{_ as i,o as a,c as t,a3 as s}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Building from Source","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Building from Source | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/dev/build"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/dev/build"}]]},"headers":[],"relativePath":"catter/dev/build.md","filePath":"en/catter/dev/build.md","lastUpdated":1792996862000}'),n={name:"catter/dev/build.md"};function o(r,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="building-from-source" tabindex="-1">Building from Source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from Source&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="https://pixi.sh" target="_blank" rel="noreferrer">pixi</a> -- Environment and dependency management; it brings everything else, Bazel included</li><li>Git</li></ul><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Target</th><th>Built on</th></tr></thead><tbody><tr><td>Linux x64</td><td><code>x86_64-unknown-linux-gnu</code></td><td>Linux</td></tr><tr><td>macOS arm64</td><td><code>aarch64-apple-darwin</code></td><td>macOS</td></tr><tr><td>Windows x64</td><td><code>x86_64-w64-mingw32</code></td><td>Linux, Windows</td></tr><tr><td>Windows on ARM</td><td><code>aarch64-w64-mingw32</code></td><td>Linux, Windows</td></tr></tbody></table><p>Every platform builds with the toolchain of <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a> 23.1.3, which Bazel downloads: clang, lld and libc++, linked into each program, so a program depends on the system&#39;s libraries alone. Linux programs run on glibc 2.17 and later, macOS programs on macOS 15 and later. The Windows programs are MinGW&#39;s, and every Windows build makes the hook DLLs of both architectures, x64 and ARM64.</p><h2 id="build-commands" tabindex="-1">Build Commands <a class="header-anchor" href="#build-commands" aria-label="Permalink to &quot;Build Commands&quot;">​</a></h2><p>All builds are managed through pixi tasks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the programs, the hook libraries and the unit tests (RelWithDebInfo)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The ASan build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build for Windows on ARM from Linux or Windows x64</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RelWithDebInfo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platforms=@xclang//platforms:aarch64-w64-mingw32</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The release package, build/RelWithDebInfo/bin/catter.tar.gz (catter.zip on Windows)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RelWithDebInfo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:package</span></span></code></pre></div><p>The programs are built into <code>build/&lt;type&gt;/bin/bin</code>, side by side as catter finds them. The build types are <code>RelWithDebInfo</code>, optimized with debug information, what releases ship, and <code>Debug</code>, with AddressSanitizer, which Windows on ARM has not.</p><p>On Windows, Bazel&#39;s default output root is too deep for Windows paths; put a short one in <code>%USERPROFILE%\\.bazelrc</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startup --output_user_root=C:/b</span></span></code></pre></div><h2 id="build-system" tabindex="-1">Build System <a class="header-anchor" href="#build-system" aria-label="Permalink to &quot;Build System&quot;">​</a></h2><p>The project uses <a href="https://bazel.build" target="_blank" rel="noreferrer">Bazel</a>, run through bazelisk from npm (<code>pnpm exec bazel</code>) at the version of <code>.bazelversion</code>; its dependencies come from the clice Bazel registry, <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a>. The C++ standard is C++23. <code>pixi run -e dev pnpm exec bazel run @compdb//:refresh</code> writes <code>compile_commands.json</code> for editors.</p><h3 id="build-targets" tabindex="-1">Build Targets <a class="header-anchor" href="#build-targets" aria-label="Permalink to &quot;Build Targets&quot;">​</a></h3><ul><li><code>bin/catter</code> -- Main CLI executable (the DECISION daemon)</li><li><code>bin/catter-proxy</code> -- Proxy process manager</li><li><code>hook_unix_payload</code> -- Unix hook shared library (Linux/macOS), <code>bin/libcatter-hook-unix.so</code> or <code>.dylib</code></li><li><code>hook_x64_payload</code>, <code>hook_arm64_payload</code> -- Windows hook DLLs, <code>bin/catter-hook-x64.dll</code> and <code>bin/catter-hook-arm64.dll</code>, one per architecture, both built by every Windows build</li><li><code>support</code>, <code>command</code>, <code>session</code>, <code>capture</code> (with <code>capture_inject</code>), <code>protocol</code>, <code>feature</code> -- Libraries, one per directory of <code>src/</code></li><li><code>dist</code> -- what <code>pixi run -e dev build</code> builds; <code>package</code> and <code>symbols</code> -- the release package and its debug symbols</li></ul><h2 id="key-dependencies" tabindex="-1">Key Dependencies <a class="header-anchor" href="#key-dependencies" aria-label="Permalink to &quot;Key Dependencies&quot;">​</a></h2><ul><li><a href="https://github.com/gabime/spdlog" target="_blank" rel="noreferrer">spdlog</a> (1.15.3) -- Logging</li><li><a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a> -- Async runtime, testing framework, option parsing</li><li><a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a> -- Windows API hooking and DLL injection (Windows only)</li></ul>`,18)])])}const k=i(n,[["render",o]]);export{u as __pageData,k as default};
